import { createRoute, z } from '@hono/zod-openapi'

type LegalEntityAddressType = {
  address_types: (
    | 'business'
    | 'business_physical'
    | 'business_registered'
    | 'mailing'
    | 'other'
    | 'po_box'
    | 'residential'
  )[]
  country: string | null
  created_at: string
  discarded_at: string | null
  id: string
  line1: string | null
  line2: string | null
  live_mode: boolean
  locality: string | null
  object: string
  postal_code: string | null
  primary: boolean | null
  region: string | null
  updated_at: string
}

const LegalEntityAddressSchema: z.ZodType<LegalEntityAddressType> = z
  .strictObject({
    address_types: z
      .array(
        z.enum([
          'business',
          'business_physical',
          'business_registered',
          'mailing',
          'other',
          'po_box',
          'residential',
        ]),
      )
      .openapi({ description: 'The types of this address.' }),
    country: z
      .string()
      .nullable()
      .openapi({ description: 'Country code conforms to [ISO 3166-1 alpha-2]' }),
    created_at: z.iso.datetime({ offset: true }),
    discarded_at: z.iso.datetime({ offset: true }).nullable(),
    id: z.uuid(),
    line1: z.string().nullable(),
    line2: z.string().nullable(),
    live_mode: z
      .boolean()
      .openapi({
        description:
          'This field will be true if this object exists in the live environment or false if it exists in the test environment.',
      }),
    locality: z
      .string()
      .nullable()
      .openapi({
        description:
          'Locality or City. Use the full city name rather than an abbreviation (e.g. San Francisco).',
      }),
    object: z.string(),
    postal_code: z.string().nullable().openapi({ description: 'The postal code of the address.' }),
    primary: z
      .boolean()
      .nullable()
      .openapi({
        description:
          'Whether this address is the primary address for the legal entity. Optional; when omitted it is inferred from the address types.',
      }),
    region: z
      .string()
      .nullable()
      .openapi({
        description:
          'Region or State. This field is free-form; for US states, we recommend a two-letter code (e.g. CA). Full state names are also accepted.',
      }),
    updated_at: z.iso.datetime({ offset: true }),
  })
  .refine((val) => Object.keys(val).length >= 14)
  .openapi({
    required: [
      'id',
      'object',
      'live_mode',
      'created_at',
      'updated_at',
      'discarded_at',
      'address_types',
      'primary',
      'line1',
      'line2',
      'locality',
      'region',
      'postal_code',
      'country',
    ],
  })
  .openapi('LegalEntityAddress')

type LegalEntityBankSettingType = {
  backup_withholding_percentage: number | null
  created_at: string
  discarded_at: string | null
  enable_backup_withholding: boolean | null
  id: string
  live_mode: boolean
  object: string
  privacy_opt_out: boolean | null
  regulation_o: boolean | null
  updated_at: string
}

const LegalEntityBankSettingSchema: z.ZodType<LegalEntityBankSettingType> = z
  .strictObject({
    backup_withholding_percentage: z
      .int()
      .nullable()
      .openapi({
        description: 'The percentage of backup withholding to apply to the legal entity.',
      }),
    created_at: z.iso.datetime({ offset: true }),
    discarded_at: z.iso.datetime({ offset: true }).nullable(),
    enable_backup_withholding: z
      .boolean()
      .nullable()
      .openapi({
        description:
          'Whether backup withholding is enabled. See more here - https://www.irs.gov/businesses/small-businesses-self-employed/backup-withholding.',
      }),
    id: z.uuid(),
    live_mode: z
      .boolean()
      .openapi({
        description:
          'This field will be true if this object exists in the live environment or false if it exists in the test environment.',
      }),
    object: z.string(),
    privacy_opt_out: z
      .boolean()
      .nullable()
      .openapi({ description: 'Cross River Bank specific setting to opt out of privacy policy.' }),
    regulation_o: z
      .boolean()
      .nullable()
      .openapi({
        description:
          'It covers, among other types of insider loans, extensions of credit by a member bank to an executive officer, director, or principal shareholder of the member bank; a bank holding company of which the member bank is a subsidiary; and any other subsidiary of that bank holding company.',
      }),
    updated_at: z.iso.datetime({ offset: true }),
  })
  .refine((val) => Object.keys(val).length >= 10)
  .openapi({
    required: [
      'id',
      'object',
      'live_mode',
      'created_at',
      'updated_at',
      'discarded_at',
      'enable_backup_withholding',
      'backup_withholding_percentage',
      'privacy_opt_out',
      'regulation_o',
    ],
  })
  .openapi('LegalEntityBankSetting')

type DocumentType = {
  created_at: string
  discarded_at: string | null
  document_type: string | null
  documentable_id: string | null
  documentable_type:
    | 'connection'
    | 'counterparty'
    | 'expected_payment'
    | 'identification'
    | 'incoming_payment_detail'
    | 'internal_account'
    | 'legal_entity'
    | 'payment_order'
    | 'return'
    | 'transaction'
    | null
  file: { content_type?: string; filename?: string; size?: number }
  id: string
  live_mode: boolean
  object: string
  source: string
  updated_at: string
}

const DocumentSchema: z.ZodType<DocumentType> = z
  .object({
    created_at: z.iso.datetime({ offset: true }),
    discarded_at: z.iso.datetime({ offset: true }).nullable(),
    document_type: z
      .string()
      .nullable()
      .openapi({ description: 'A category given to the document, can be `null`.' }),
    documentable_id: z
      .uuid()
      .nullable()
      .openapi({ description: 'The unique identifier for the associated object.' }),
    documentable_type: z
      .enum([
        'connection',
        'counterparty',
        'expected_payment',
        'identification',
        'incoming_payment_detail',
        'internal_account',
        'legal_entity',
        'payment_order',
        'return',
        'transaction',
      ])
      .nullable()
      .openapi({
        description:
          'The type of the associated object. Currently can be one of `connection`, `counterparty`, `expected_payment`, `identification`, `incoming_payment_detail`, `internal_account`, `legal_entity`, `payment_order`, `return`, or `transaction`.',
      }),
    file: z
      .strictObject({
        content_type: z
          .string()
          .exactOptional()
          .openapi({ description: 'The MIME content type of the document.' }),
        filename: z
          .string()
          .exactOptional()
          .openapi({ description: 'The original filename of the document.' }),
        size: z
          .int()
          .exactOptional()
          .openapi({ description: 'The size of the document in bytes.' }),
      })
      .refine((val) => Object.keys(val).length >= 3)
      .openapi({ required: [] }),
    id: z.uuid(),
    live_mode: z
      .boolean()
      .openapi({
        description:
          'This field will be true if this object exists in the live environment or false if it exists in the test environment.',
      }),
    object: z.string(),
    source: z
      .string()
      .openapi({
        description:
          'The source of the document. Can be `vendor`, `customer`, or `modern_treasury`.',
      }),
    updated_at: z.iso.datetime({ offset: true }),
  })
  .refine((val) => Object.keys(val).length >= 11)
  .openapi({
    required: [
      'id',
      'object',
      'live_mode',
      'created_at',
      'updated_at',
      'discarded_at',
      'document_type',
      'source',
      'documentable_id',
      'documentable_type',
      'file',
    ],
  })
  .openapi('Document')

