const BulkRequestCreateRequestSchema = z
  .object({
    action_type: z
      .enum(['create', 'update', 'delete'])
      .openapi({ description: 'One of create, or update.' }),
    metadata: z
      .record(z.string(), z.string())
      .exactOptional()
      .openapi({
        description:
          'Additional data represented as key-value pairs. Both the key and value must be strings.',
        example: { foo: 'bar', key: 'value', modern: 'treasury' },
      }),
    resource_type: z
      .enum([
        'payment_order',
        'ledger_account',
        'ledger_transaction',
        'expected_payment',
        'transaction',
        'transaction_line_item',
      ])
      .openapi({ description: 'One of payment_order, expected_payment, or ledger_transaction.' }),
    resources: z
      .array(
        z.xor([
          PaymentOrderAsyncCreateRequestSchema,
          ExpectedPaymentCreateRequestSchema,
          LedgerTransactionCreateRequestSchema,
          LedgerAccountCreateRequestSchema,
          TransactionCreateRequestSchema,
          z.object({ id: z.uuid().exactOptional() }).openapi({ required: [] }),
          PaymentOrderUpdateRequestSchema.and(
            z.object({ id: z.uuid().exactOptional() }).openapi({ required: [] }),
          ),
          ExpectedPaymentUpdateRequestSchema.and(
            z.object({ id: z.uuid().exactOptional() }).openapi({ required: [] }),
          ),
          TransactionUpdateRequestSchema.and(
            z.object({ id: z.uuid().exactOptional() }).openapi({ required: [] }),
          ),
          LedgerTransactionUpdateRequestSchema.and(
            z.object({ id: z.uuid().exactOptional() }).openapi({ required: [] }),
          ),
          LedgerAccountUpdateRequestSchema.and(
            z.object({ id: z.uuid().exactOptional() }).openapi({ required: [] }),
          ),
        ]),
      )
      .openapi({
        description:
          'An array of objects where each object contains the input params for a single `action_type` request on a `resource_type` resource',
      }),
  })
  .openapi({ required: ['action_type', 'resource_type', 'resources'] })
  .openapi('BulkRequestCreateRequest')

