const ForeignExchangeRateSchema = z
  .strictObject({
    base_amount: z
      .int()
      .openapi({
        description:
          'Amount in the lowest denomination of the `base_currency` to convert, often called the "sell" amount.',
      }),
    base_currency: CurrencySchema.openapi({
      description: 'Currency to convert, often called the "sell" currency.',
    }),
    exponent: z
      .int()
      .openapi({
        description:
          'The exponent component of the rate. The decimal is calculated as `value` / (10 ^ `exponent`).',
      }),
    rate_string: z.string().openapi({ description: 'A string representation of the rate.' }),
    target_amount: z
      .int()
      .openapi({
        description:
          'Amount in the lowest denomination of the `target_currency`, often called the "buy" amount.',
      }),
    target_currency: CurrencySchema.openapi({
      description: 'Currency to convert the `base_currency` to, often called the "buy" currency.',
    }),
    value: z
      .int()
      .openapi({
        description:
          'The whole number component of the rate. The decimal is calculated as `value` / (10 ^ `exponent`).',
      }),
  })
  .openapi({
    required: [
      'base_amount',
      'base_currency',
      'exponent',
      'rate_string',
      'target_amount',
      'target_currency',
      'value',
    ],
  })
  .openapi('ForeignExchangeRate')

