      'object',
      'live_mode',
      'created_at',
      'updated_at',
      'status',
      'payment_order_id',
      'transaction_ids',
      'ledger_transaction_id',
      'metadata',
      'reason',
      'internal_account_id',
      'reconciliation_status',
