export const getApiIncomingPaymentDetailsRoute = createRoute({
  method: 'get',
  path: '/api/incoming_payment_details',
  tags: ['IncomingPaymentDetail'],
  summary: 'list incoming payment_details',
  description: 'Get a list of Incoming Payment Details.',
  operationId: 'listIncomingPaymentDetails',
  request: {
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const isGroup = (item: unknown): item is Record<string, unknown> =>
          typeof item === 'object' && item !== null && !Array.isArray(item)
        const lists = new WeakSet<object>()
        const isIndex = (part: string | undefined) => part !== undefined && /^\d*$/.test(part)
        const child = (target: Record<string, unknown>, key: string, asList: boolean) => {
          const held = target[key]
          if (isGroup(held)) return held
          const made: Record<string, unknown> = Object.create(null)
          if (asList) lists.add(made)
          target[key] = made
          return made
        }
        const set = (
          root: Record<string, unknown>,
          path: readonly string[],
          item: unknown,
        ): void => {
          const work: [Record<string, unknown>, number, unknown, boolean][] = [
            [root, 0, item, false],
          ]
          for (let job = work.pop(); job !== undefined; job = work.pop()) {
            const [target, at, value, split] = job
            const head = path[at]
            if (head === undefined) continue
            const next = path[at + 1]
            if (head === '') {
              if (!split && Array.isArray(value)) {
                for (let i = value.length - 1; i >= 0; i -= 1)
                  work.push([target, at, value[i], true])
                continue
              }
              const size = Object.keys(target).length
              if (next === undefined) {
                target[String(size)] = value
                continue
              }
              const free =
                next === ''
                  ? -1
                  : Object.values(target).findIndex((held) => isGroup(held) && !(next in held))
              work.push([
                child(target, String(free < 0 ? size : free), isIndex(next)),
                at + 1,
                value,
                false,
              ])
              continue
            }
            if (next === undefined) {
              target[head] = value
              continue
            }
            work.push([child(target, head, isIndex(next)), at + 1, value, false])
          }
        }
        const settle = (root: unknown): unknown => {
          if (!isGroup(root)) return root
          const found: [Record<string, unknown>, string, Record<string, unknown>][] = []
          const queue: Record<string, unknown>[] = [root]
          for (const node of queue) {
            for (const [key, inner] of Object.entries(node)) {
              if (isGroup(inner)) {
                found.push([node, key, inner])
                queue.push(inner)
              }
            }
          }
          const finish = (group: Record<string, unknown>): unknown =>
            lists.has(group)
              ? Object.entries(group)
                  .sort((a, b) => Number(a[0]) - Number(b[0]))
                  .map(([, inner]) => inner)
              : Object.assign(Object.create(null), group)
          for (const [parent, key, group] of found.reverse()) {
            parent[key] = finish(group)
          }
          return finish(root)
        }
        const deep: string[] = ['metadata']
        for (const [key, item] of Object.entries(val)) {
          const match = /^([^\[\]]+)((?:\[[^\[\]]*\])+)$/.exec(key)
          const name = match?.[1]
          const path = match?.[2]
          if (name !== undefined && path !== undefined && deep.includes(name)) {
            const parts = path.slice(1, -1).split('][')
            set(group(name), parts, item)
            continue
          }
          rest.push([key, item])
        }
        return Object.fromEntries([
          ...rest,
          ...[...groups].map(([name, held]) => [name, settle(held)] as const),
        ])
      })
      .pipe(
        z.object({
          after_cursor: z
            .string()
            .nullable()
            .exactOptional()
            .openapi({
              param: {
                name: 'after_cursor',
                in: 'query',
                schema: { nullable: true, type: 'string' },
                required: false,
              },
            }),
          as_of_date_end: z.iso
            .date()
            .exactOptional()
            .openapi({
              param: {
                name: 'as_of_date_end',
                in: 'query',
                schema: { format: 'date', type: 'string' },
                required: false,
                description:
                  'Filters incoming payment details with an as_of_date starting on or before the specified date (YYYY-MM-DD).',
              },
            }),
          as_of_date_start: z.iso
            .date()
            .exactOptional()
            .openapi({
              param: {
                name: 'as_of_date_start',
                in: 'query',
                schema: { format: 'date', type: 'string' },
                required: false,
                description:
                  'Filters incoming payment details with an as_of_date starting on or after the specified date (YYYY-MM-DD).',
              },
            }),
          direction: z
            .enum(['credit', 'debit'])
            .exactOptional()
            .openapi({
              param: {
                name: 'direction',
                in: 'query',
                schema: { enum: ['credit', 'debit'], type: 'string' },
                required: false,
                description: 'One of `credit` or `debit`.',
              },
            }),
          per_page: z
            .preprocess(
              (val) =>
                typeof val === 'string' &&
                /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                  ? Number(val)
                  : val,
              z.int(),
            )
            .exactOptional()
            .openapi({
              param: {
                name: 'per_page',
                in: 'query',
                schema: { type: 'integer' },
                required: false,
              },
            }),
          status: z
            .enum(['completed', 'failed', 'held', 'pending', 'returned'])
            .exactOptional()
            .openapi({
              param: {
                name: 'status',
                in: 'query',
                schema: {
                  enum: ['completed', 'failed', 'held', 'pending', 'returned'],
                  type: 'string',
                },
                required: false,
                description:
                  'The current status of the incoming payment order. One of `pending`, `completed`, `returned`, `failed`, or `held`.',
              },
            }),
          subtype: z
            .string()
            .exactOptional()
            .openapi({
              param: {
                name: 'subtype',
                in: 'query',
                schema: { type: 'string' },
                required: false,
                description:
                  'An additional layer of classification for the type of incoming payment detail. For example, a `type` of `stablecoin` may have a `subtype` of `ethereum` or `solana`.',
              },
            }),
          type: z
            .enum([
              'ach',
              'au_becs',
              'bacs',
              'book',
              'check',
              'eft',
              'neft',
              'nz_becs',
              'rtp',
              'sepa',
              'stablecoin',
              'wire',
              'zengin',
            ])
            .exactOptional()
            .openapi({
              param: {
                name: 'type',
                in: 'query',
                schema: {
                  enum: [
                    'ach',
                    'au_becs',
                    'bacs',
                    'book',
                    'check',
                    'eft',
                    'neft',
                    'nz_becs',
                    'rtp',
                    'sepa',
                    'stablecoin',
                    'wire',
                    'zengin',
                  ],
                  type: 'string',
                },
                required: false,
                description: 'One of: `ach`, `book`, `check`, `eft`, `rtp`, `sepa`, or `wire`.',
              },
            }),
          virtual_account_id: z
            .uuid()
            .exactOptional()
            .openapi({
              param: {
                name: 'virtual_account_id',
                in: 'query',
                schema: { format: 'uuid', type: 'string' },
                required: false,
                description:
                  'If the incoming payment detail is in a virtual account, the ID of the Virtual Account.',
              },
            }),
          metadata: MetadataQueryParamsSchema,
        }),
      ),
  },
  responses: {
    200: {
      description: 'successful',
      content: { 'application/json': { schema: z.array(IncomingPaymentDetailSchema) } },
      headers: z.object({
        'X-After-Cursor': z
          .string()
          .nullable()
          .exactOptional()
          .openapi({
            description:
              'The cursor for the next page. Including this in a call as `after_cursor` will return the next page.',
            param: { required: false },
          }),
        'X-Per-Page': z
          .int()
          .nullable()
          .exactOptional()
          .openapi({ description: 'The current `per_page`.', param: { required: false } }),
      }),
    },
    400: {
      description: 'bad request',
      content: { 'application/json': { schema: ErrorMessageSchema } },
    },
    401: {
      description: 'unsuccessful',
      content: { 'application/json': { schema: ErrorMessageSchema } },
    },
    403: {
      description: 'forbidden',
      content: { 'application/json': { schema: ErrorMessageSchema } },
    },
    429: { description: 'too many requests' },
  },
  security: [{ basic_auth: [] }],
})

