export const getApiInvoicesRoute = createRoute({
  method: 'get',
  path: '/api/invoices',
  tags: ['Invoice'],
  summary: 'list invoices',
  operationId: 'listInvoices',
  request: {
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const isGroup = (item: unknown): item is Record<string, unknown> =>
          typeof item === 'object' && item !== null && !Array.isArray(item)
        const lists = new WeakSet<object>()
        const isIndex = (part: string | undefined) => part !== undefined && /^\d*$/.test(part)
        const child = (target: Record<string, unknown>, key: string, asList: boolean) => {
          const held = target[key]
          if (isGroup(held)) return held
          const made: Record<string, unknown> = Object.create(null)
          if (asList) lists.add(made)
          target[key] = made
          return made
        }
        const set = (
          root: Record<string, unknown>,
          path: readonly string[],
          item: unknown,
        ): void => {
          const work: [Record<string, unknown>, number, unknown, boolean][] = [
            [root, 0, item, false],
          ]
          for (let job = work.pop(); job !== undefined; job = work.pop()) {
            const [target, at, value, split] = job
            const head = path[at]
            if (head === undefined) continue
            const next = path[at + 1]
            if (head === '') {
              if (!split && Array.isArray(value)) {
                for (let i = value.length - 1; i >= 0; i -= 1)
                  work.push([target, at, value[i], true])
                continue
              }
              const size = Object.keys(target).length
              if (next === undefined) {
                target[String(size)] = value
                continue
              }
              const free =
                next === ''
                  ? -1
                  : Object.values(target).findIndex((held) => isGroup(held) && !(next in held))
              work.push([
                child(target, String(free < 0 ? size : free), isIndex(next)),
                at + 1,
                value,
                false,
              ])
              continue
            }
            if (next === undefined) {
              target[head] = value
              continue
            }
            work.push([child(target, head, isIndex(next)), at + 1, value, false])
          }
        }
        const settle = (root: unknown): unknown => {
          if (!isGroup(root)) return root
          const found: [Record<string, unknown>, string, Record<string, unknown>][] = []
          const queue: Record<string, unknown>[] = [root]
          for (const node of queue) {
            for (const [key, inner] of Object.entries(node)) {
              if (isGroup(inner)) {
                found.push([node, key, inner])
                queue.push(inner)
              }
            }
          }
          const finish = (group: Record<string, unknown>): unknown =>
            lists.has(group)
              ? Object.entries(group)
                  .sort((a, b) => Number(a[0]) - Number(b[0]))
                  .map(([, inner]) => inner)
              : Object.assign(Object.create(null), group)
          for (const [parent, key, group] of found.reverse()) {
            parent[key] = finish(group)
          }
          return finish(root)
        }
        const deep: string[] = ['metadata']
        for (const [key, item] of Object.entries(val)) {
          const match = /^([^\[\]]+)((?:\[[^\[\]]*\])+)$/.exec(key)
          const name = match?.[1]
          const path = match?.[2]
          if (name !== undefined && path !== undefined && deep.includes(name)) {
            const parts = path.slice(1, -1).split('][')
            set(group(name), parts, item)
            continue
          }
          rest.push([key, item])
        }
        return Object.fromEntries([
          ...rest,
          ...[...groups].map(([name, held]) => [name, settle(held)] as const),
        ])
      })
      .pipe(
        z.object({
          after_cursor: z
            .string()
            .nullable()
            .exactOptional()
            .openapi({
              param: {
                name: 'after_cursor',
                in: 'query',
                schema: { nullable: true, type: 'string' },
                required: false,
              },
            }),
          counterparty_id: z
            .uuid()
            .exactOptional()
            .openapi({
              param: {
                name: 'counterparty_id',
                in: 'query',
                schema: { format: 'uuid', type: 'string' },
                required: false,
              },
            }),
          created_at_end: z.iso
            .datetime({ offset: true })
            .exactOptional()
            .openapi({
              param: {
                name: 'created_at_end',
                in: 'query',
                schema: { format: 'date-time', type: 'string' },
                required: false,
                description: 'An inclusive upper bound for searching created_at',
              },
            }),
          created_at_start: z.iso
            .datetime({ offset: true })
            .exactOptional()
            .openapi({
              param: {
                name: 'created_at_start',
                in: 'query',
                schema: { format: 'date-time', type: 'string' },
                required: false,
                description: 'An inclusive lower bound for searching created_at',
              },
            }),
          due_date_end: z.iso
            .date()
            .exactOptional()
            .openapi({
              param: {
                name: 'due_date_end',
                in: 'query',
                schema: { format: 'date', type: 'string' },
                required: false,
                description: 'An inclusive upper bound for searching due_date',
              },
            }),
          due_date_start: z.iso
            .date()
            .exactOptional()
            .openapi({
              param: {
                name: 'due_date_start',
                in: 'query',
                schema: { format: 'date', type: 'string' },
                required: false,
                description: 'An inclusive lower bound for searching due_date',
              },
            }),
          expected_payment_id: z
            .uuid()
            .exactOptional()
            .openapi({
              param: {
                name: 'expected_payment_id',
                in: 'query',
                schema: { format: 'uuid', type: 'string' },
                required: false,
              },
            }),
          number: z
            .string()
            .exactOptional()
            .openapi({
              param: {
                name: 'number',
                in: 'query',
                schema: { type: 'string' },
                required: false,
                description: 'A unique record number assigned to each invoice that is issued.',
              },
            }),
          originating_account_id: z
            .uuid()
            .exactOptional()
            .openapi({
              param: {
                name: 'originating_account_id',
                in: 'query',
                schema: { format: 'uuid', type: 'string' },
                required: false,
              },
            }),
          payment_order_id: z
            .uuid()
            .exactOptional()
            .openapi({
              param: {
                name: 'payment_order_id',
                in: 'query',
                schema: { format: 'uuid', type: 'string' },
                required: false,
              },
            }),
          per_page: z
            .preprocess(
              (val) =>
                typeof val === 'string' &&
                /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                  ? Number(val)
                  : val,
              z.int(),
            )
            .exactOptional()
            .openapi({
              param: {
                name: 'per_page',
                in: 'query',
                schema: { type: 'integer' },
                required: false,
              },
            }),
          status: z
            .enum(['draft', 'paid', 'partially_paid', 'payment_pending', 'unpaid', 'voided'])
            .exactOptional()
            .openapi({
              param: {
                name: 'status',
                in: 'query',
                schema: {
                  enum: ['draft', 'paid', 'partially_paid', 'payment_pending', 'unpaid', 'voided'],
                  type: 'string',
                },
                required: false,
              },
            }),
          metadata: MetadataQueryParamsSchema,
        }),
      ),
  },
  responses: {
    200: {
      description: 'successful',
      content: { 'application/json': { schema: z.array(InvoiceSchema) } },
      headers: z.object({
        'X-After-Cursor': z
          .string()
          .nullable()
          .exactOptional()
          .openapi({
            description:
              'The cursor for the next page. Including this in a call as `after_cursor` will return the next page.',
            param: { required: false },
          }),
        'X-Per-Page': z
          .int()
          .nullable()
          .exactOptional()
          .openapi({ description: 'The current `per_page`.', param: { required: false } }),
      }),
    },
    400: {
      description: 'bad request',
      content: { 'application/json': { schema: ErrorMessageSchema } },
    },
    401: {
      description: 'unsuccessful',
      content: { 'application/json': { schema: ErrorMessageSchema } },
    },
    403: {
      description: 'forbidden',
      content: { 'application/json': { schema: ErrorMessageSchema } },
    },
    429: { description: 'too many requests' },
  },
  security: [{ basic_auth: [] }],
})

